function handler(event) {
  var request = event.request;
  var cutoff = Date.parse('${CreditCutoffAt}Z');
  if (!isFinite(cutoff) || Date.now() >= cutoff) return {statusCode:503,statusDescription:'Service unavailable',headers:{'cache-control':{value:'no-store'},'content-type':{value:'text/plain; charset=utf-8'}},body:'This environment is paused for a funding review.'};
  var authorization = request.headers.authorization;
  var machine = request.headers['x-beter-staging-access'];
  var candidate = machine ? machine.value : authorization ? authorization.value : '';
  if ('${LaunchOpen}' !== 'true') {
    var crypto = require('crypto');
    if (!candidate || crypto.createHash('sha256').update(candidate).digest('hex') !== '${StagingAuthorizationHash}') return {statusCode:401,statusDescription:'Authentication required',headers:{'www-authenticate':{value:'Basic realm="Beter staging", charset="UTF-8"'},'cache-control':{value:'no-store'},'content-type':{value:'text/plain; charset=utf-8'}},body:'This staging environment requires access credentials.'};
  }
  if (authorization && authorization.value.indexOf('Basic ') === 0) delete request.headers.authorization;
  delete request.headers['x-beter-staging-access'];
  request.headers['x-beter-viewer-ip'] = {value:event.viewer.ip};
  return request;
}
